export type Customer = {
  yearsWithMHPCO: number;
  previousContracts: number;
};

export type Item = {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
};

const PROCESSING_FEE = 5;

const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const CURSED_SURCHARGE_RATE = 0.5;
const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
const HIGH_ENCHANTMENT_THRESHOLD = 5;

const basePremiumOf = (item: Item): number =>
  BASE_PREMIUM_BY_ITEM_TYPE[item.type];

const itemModifierRateOf = (item: Item): number =>
  (item.cursed ? CURSED_SURCHARGE_RATE : 0) +
  ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD
    ? HIGH_ENCHANTMENT_SURCHARGE_RATE
    : 0);

const premiumOf = (item: Item): number =>
  basePremiumOf(item) * (1 + itemModifierRateOf(item));

const sumItemPremiums = (items: Item[]): number =>
  items.reduce((sum, item) => sum + premiumOf(item), 0);

// Policy-level modifiers are whole percentages of the policy base premium.
// Applying them as `amount * percent / 100` keeps the arithmetic exact:
// `100 * 110 / 100` is 110, whereas `100 * 1.1` is 110.00000000000001.
const applyPercentage = (amount: number, percent: number): number =>
  (amount * percent) / 100;

const FIRST_INSURANCE_PERCENTAGE = 110;

const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

const isComponentBlock = (sameTypeGroup: Item[]): boolean =>
  sameTypeGroup.length === BLOCK_SIZE;

const groupByType = (items: Item[]): Item[][] => {
  const groups = new Map<string, Item[]>();
  for (const item of items) {
    const group = groups.get(item.type) ?? [];
    group.push(item);
    groups.set(item.type, group);
  }
  return [...groups.values()];
};

const premiumOfGroup = (sameTypeGroup: Item[]): number =>
  isComponentBlock(sameTypeGroup)
    ? BLOCK_BASE_PREMIUM
    : sumItemPremiums(sameTypeGroup);

export const quote = (customer: Customer, items: Item[]): number => {
  const policyPremium = groupByType(items).reduce(
    (sum, group) => sum + premiumOfGroup(group),
    0,
  );

  const withFirstInsuranceSurcharge = applyPercentage(
    policyPremium,
    FIRST_INSURANCE_PERCENTAGE,
  );

  return withFirstInsuranceSurcharge + PROCESSING_FEE;
};

export const claim = (): number => {
  return undefined as unknown as number;
};

